import{_ as n,l as i,o as e,c as l,v as t,p as s,x as r,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"舍入误差如何传播","description":"","frontmatter":{"title":"舍入误差如何传播","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fp-error-propagation.md","filePath":"cs/fp-error-propagation.md","lastUpdated":1789023840000}'),E={name:"cs/fp-error-propagation.md"};function h(c,a,_,u,A,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="舍入误差如何传播" tabindex="-1">舍入误差如何传播 <a class="header-anchor" href="#舍入误差如何传播" aria-label="Permalink to &quot;舍入误差如何传播&quot;">​</a></h1><div class="epigraph"><p>每次浮点运算把精确结果再映回有限集合；分析算法时要把这次映回写成乘在结果上的 $(1+\\delta)$，而不是假装在实数域演算。</p><footer>—— 据 Higham, Accuracy and Stability of Numerical Algorithms；Golub and Van Loan, Matrix Computations 整理</footer></div><p>上一课<a href="/cs/conditional-bayes">条件概率与贝叶斯</a>收束信息与离散主干：有限对象上的条件与反转已经钉死。<a href="/cs/ieee-754">IEEE 754</a> 已经给出位型、偏置指数与默认舍入。本课是「数值计算」第一课；后课默认已经读完本课。不重讲概率，也不从符号位、尾数宽度另起。缺口是：格式已经固定，<strong>一步舍入怎样写进代数、多步之后误差项如何长到终点</strong>。问题本身有多敏感，交给<a href="/cs/condition-number">条件数</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实数 \\(x\\) 在机器上变成 \\(\\mathrm{fl}(x)=x(1+\\varepsilon)\\)，\\(|\\varepsilon|\\le u\\)，其中 \\(u\\) 是舍入单位。算术运算 \\(\\circ\\) 的模型是 \\(\\mathrm{fl}(a\\circ b)=(a\\circ b)(1+\\delta)\\)，\\(|\\delta|\\le u\\)（在不溢出的前提下）。缺口因此不是「浮点不精确」的口号，而是<strong>可传递的误差代数</strong>：把每一步的 \\(\\delta\\) 乘进后续运算，得到对终点的界。没有这套记号，后课稳定与消去只会剩下一堆反例。</p><p>信息课已经说明 NaN 与无穷是编码；本课假定运算落在规格化有限数上，例外与非规格化不在此展开。贝叶斯课的「误差」是概率质量；这里的误差是舍入引入的相对扰动，对象不同。</p><h3 id="传播不是条件数" tabindex="-1">传播不是条件数 <a class="header-anchor" href="#传播不是条件数" aria-label="Permalink to &quot;传播不是条件数&quot;">​</a></h3><p>条件数问：数据里已有的扰动被问题放大多少。本课问：算法在机器上每步新注入多少舍入。总误差大致是「问题放大 × 算法注入」。把二者都叫做「数值不稳定」，后课无法分工：病态问题即使用精确算术也会大变；不稳定算法则在良态问题上也会毁掉位数。</p><p><span class="marginnote">Higham 用 \\(\\mathrm{fl}\\) 与 \\(\\gamma_n\\) 把舍入写成可计算的乘性扰动。Golub and Van Loan 把同一套用在矩阵乘与分解。Wilkinson 的早期浮点误差代数是源头，本课按 Higham 的记号走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(\\gamma_n=nu/(1-nu)\\)（当 \\(nu\\lt 1\\)）。\\(n\\) 次乘加的朴素界用 \\(\\gamma_n\\) 吸收「每次一个 \\(u\\) 再相乘」的高阶项。标量求和 \\(\\hat s=\\mathrm{fl}(x_1+\\cdots+x_n)\\) 满足 \\(|\\hat s-s|\\le \\gamma_{n-1}\\sum|x_i|\\) 量级。内积、矩阵乘把同一计数换成「每个输出经过多少次乘加」。</p>',11)),(e(),s(p,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXACT%5B%22%E5%AE%9E%E6%95%B0%E8%BF%90%E7%AE%97%22%5D%20--%3E%20FL%5B%22%E6%AF%8F%E6%AD%A5%20fl%20%E5%BC%95%E5%85%A5%20delta%22%5D%0A%20%20FL%20--%3E%20ACC%5B%22%E8%AF%AF%E5%B7%AE%E6%B2%BF%E6%95%B0%E6%8D%AE%E6%B5%81%E4%BC%A0%E6%92%AD%22%5D%0A%20%20ACC%20--%3E%20Y%5B%22%E6%9C%BA%E5%99%A8%E7%BB%93%E6%9E%9C%22%5D%0A%20%20PROB%5B%22%E9%97%AE%E9%A2%98%E6%9D%A1%E4%BB%B6%E6%95%B0%22%5D%20--%3E%20TOT%5B%22%E6%80%BB%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20ACC%20--%3E%20TOT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>本课只给前向图像：\\(\\hat y-y\\)。把 \\(\\hat y\\) 解释成「某个近旁问题的精确解」是后课后向稳定。求和顺序与补偿算法只点名，算法在<a href="/cs/summation-order">求和顺序</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>相对误差在乘法下近似相加（对数量级），在加减下取决于是否相近相消——那是消去课。传播分析的用处是：看出误差如何随运算次数线性或更糟地长，从而知道 \\(n\\) 很大时朴素三重循环不只是慢，界也变宽。FMA 少一次舍入，会改 \\(\\delta\\) 的个数，不改 754 位型。后课线性代数把同一 \\(\\gamma_n\\) 接到分解与迭代。</p><p>相对模型在加减时并不总是忠实：若结果的量级远小于操作数，相对误差相对真值可以爆掉，那是消去课。本课的 \\(\\gamma_n\\) 先假定没有这种抵消，给出「普通乘加链」的尺度，用来比较算法：同样 \\(n\\) 次运算，有的把常数藏进 \\(\\gamma_n\\)，有的把 \\(n\\) 变成 \\(n^2\\)。矩阵乘的三种循环顺序在精确算术里相同，在浮点里给出不同的 \\(E\\)，但通常仍是同一量级的 \\(\\|E\\|\\le\\gamma_n\\|A\\|\\,\\|B\\|\\)。后课条件数把这个 \\(E\\) 当成数据扰动来读，前向误差才有问题这一侧的乘数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重画 IEEE 位域，不讲异常标志。区间算术是另一套工具。后课默认：有限精度运算写成 \\((1+\\delta)\\)；复合用 \\(\\gamma_n\\) 计量；总误差要与条件数分工。下一课定义条件数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>舍入写成相对扰动 \\(\\delta\\)；多步用 \\(\\gamma_n\\) 界跟踪。</li><li>传播描述算法注入；条件数描述问题放大。不重写 754 格式。</li><li>内积与矩阵乘的误差计数来自乘加次数。</li><li>出处：Higham；Golub and Van Loan。</li></ul>',8))])}const b=n(E,[["render",h]]);export{g as __pageData,b as default};
